import '../models/masonry_result.dart';
class MasonryReferencePreset { final MasonryType type; final MasonryUnitSize unitSize; final double thicknessMm,unitRate,cementRatePerBag,sandRatePerM3,wastagePercent,masonDaysPerM3,helperDaysPerM3,masonWage,helperWage; final String note; const MasonryReferencePreset({required this.type,required this.unitSize,required this.thicknessMm,required this.unitRate,required this.cementRatePerBag,required this.sandRatePerM3,required this.wastagePercent,required this.masonDaysPerM3,required this.helperDaysPerM3,required this.masonWage,required this.helperWage,required this.note}); }
class MasonryReferenceDefaults { static MasonryReferencePreset forType(MasonryType type) { final size=switch(type){MasonryType.clayBrick=>const MasonryUnitSize(lengthMm:190,widthMm:90,heightMm:90),MasonryType.aacBlock=>const MasonryUnitSize(lengthMm:600,widthMm:200,heightMm:200),MasonryType.concreteBlock=>const MasonryUnitSize(lengthMm:400,widthMm:200,heightMm:200),MasonryType.lateriteStone=>const MasonryUnitSize(lengthMm:355.6,widthMm:228.6,heightMm:177.8)}; final rate=switch(type){MasonryType.clayBrick=>12.0,MasonryType.aacBlock=>80.0,MasonryType.concreteBlock=>50.0,MasonryType.lateriteStone=>40.0}; return MasonryReferencePreset(type:type,unitSize:size,thicknessMm:type==MasonryType.clayBrick?230:200,unitRate:rate,cementRatePerBag:450,sandRatePerM3:1800,wastagePercent:5,masonDaysPerM3:1.2,helperDaysPerM3:1.5,masonWage:900,helperWage:650,note:'Reference values — editable. Verify locally for the selected material and site conditions.'); } }
